create or replace function private.t_rules() returns trigger language plpgsql security definer set search_path to 'pg_catalog','api' as $function$
declare lim numeric; used numeric;
begin
  if tg_op='INSERT' then
    if new.status_id <> 20000 then raise exception 'Новая заявка создаётся в статусе «Черновик»' using errcode='23514'; end if;
    return new;
  end if;
  if new.status_id <> old.status_id then
    if not ((select ord from api.status where id=new.status_id) = (select ord from api.status where id=old.status_id)+1 and new.status_id <> 20004 and old.status_id <> 20003)
       and not (old.status_id=20002 and new.status_id in (20003,20004)) then
      raise exception 'Недопустимый переход статуса' using errcode='23514';
    end if;
  end if;
  if new.status_id in (20003,20004) and (new.verdict is null or btrim(new.verdict)='') then
    raise exception 'Нужно заключение эксперта' using errcode='23514';
  end if;
  if new.status_id = 20003 then
    select funding_limit into lim from api.company where id=new.company_id for update;
    if lim is not null then
      select coalesce(sum(amount),0) into used from api.application
        where company_id=new.company_id and status_id=20003 and id<>new.id;
      if new.amount > lim - used then
        raise exception 'Сумма превышает остаток лимита компании (лимит %, уже одобрено %)', lim, used using errcode='23514';
      end if;
    end if;
  end if;
  return new;
end $function$;
alter table api.application add constraint amount_not_nan check (amount <> 'NaN'::numeric);

